node --input-type=module <<'NODE'
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.route('**/game.js', async route => {
  const response = await route.fetch();
  const source = await response.text();
  await route.fulfill({ response, body: `${source}\nwindow.__test = { game, player, interact };` });
});
await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load' });
const continueScene = async () => { await page.locator('#continue-cutscene').click(); await page.waitForTimeout(100); };
const activateAt = async (x, z) => page.evaluate(({ x, z }) => { window.__test.player.position.set(x, 1.8, z); window.__test.interact(); }, { x, z });
const status = async () => ({ objective: await page.locator('#objective-text').innerText(), relays: await page.locator('#relay-value').innerText() });
await continueScene();
for (const [label, point] of [['one', [-10, -4]], ['two', [10, -10]], ['three', [0, 7]]]) {
  await activateAt(...point);
  console.log(`relay ${label}:`, await status());
  await continueScene();
}
await activateAt(0, 0);
await continueScene();
console.log('victory:', await page.locator('#overlay-title').innerText(), await status(), 'errors:', errors);
const overlayStack = await page.evaluate(() => ({ overlayZ: getComputedStyle(document.querySelector('#message-overlay')).zIndex, controlsZ: getComputedStyle(document.querySelector('#touch-controls')).zIndex, button: document.elementFromPoint(innerWidth / 2, innerHeight / 2)?.id }));
console.log('mobile overlay layering:', overlayStack);
await page.locator('#restart-btn').click({ timeout: 5000 });
await page.waitForTimeout(800);
console.log('restart:', { cutscene: await page.locator('#cutscene-title').innerText(), relay: await page.locator('#relay-value').innerText().catch(() => null), errors });
await page.screenshot({ path: '/tmp/opencode/robot_mobile_restart.png' });
await browser.close();
NODE

